// =============================================================================
//  MeteoPlaneRadar
//  AstroGlyphs.h - the planet and sign symbols of the planets screen.
//
//  GENERATED by tools/astro_glyphs.py from simple geometry (or from a PNG a
//  designer dropped into tools/glyphs/); edit the shapes there, or touch up
//  a pixel here by hand. Each character is the coverage of one pixel in
//  sixteen steps: '.' empty, '1'..'9' then 'a'..'f' increasingly lit, 'f'
//  solid ('#' counts as solid too). The firmware blends them pixel by pixel
//  in the body's colour over whatever is underneath (see drawGlyph() in
//  ScreenPlanets.cpp), so the edges are smooth and there is no font involved.
//
//  Project: MeteoPlaneRadar - live aircraft radar on a round touchscreen
//  Author:  Petr / chiptron.cz   (vyvoj / development: chiptron.cz)
// =============================================================================
